 const alwaysChecks=[['Kak 30 Gold Skulltula Reward'],['Kak 40 Gold Skulltula Reward'],['Kak 50 Gold Skulltula Reward'],['DMT Biggoron'],['Deku Theater Skull Mask','Deku Theater Mask of Truth'],['ZR Frogs Ocarina Game','ZR Frogs in the Rain'],['HF Ocarina of Time Item','Song from Ocarina of Time']];
 function ignored(l){return alwaysChecks.some((checks,i)=>checks.some((name,j)=>name===l.name&&String(state.notes[(j?'always-second:':'always:')+i]??'').trim().toLowerCase()==='x'));}
 function singleDone(l){return data().done?.[l.name]===true||state.notes['freestanding:'+l.name]===true;}
 function done(l){return l.members?l.members.every(singleDone):singleDone(l);}
 function groupedChecks(locations){const groups=new Map();for(const l of locations){if(ignored(l))continue;const shop=l.type==='Shop';const groupable=shop||(['Freestanding','ActorOverride'].includes(l.type)&&/ \d+$/.test(l.name));let base=shop?l.name.replace(/ Item \d+$/,''):groupable?l.name.replace(/ \d+$/,'').replace(/ (?:Green|Blue|Red) Rupee/,' Rupee'):l.name;const key=groupable?[l.zone,l.age,Boolean(l.out),l.outAge??'',base].join('|'):l.name;if(!groups.has(key))groups.set(key,{...l,label:groupable?base:l.label,members:[]});groups.get(key).members.push(l);}return [...groups.values()].map(l=>({...l,label:l.label+(l.members.length>1||l.type==='Shop'?' ('+l.members.length+')':'')}));}
