 for(const [zone,locations] of ordered){const card=make('section','checks-zone'),h=make('div','checks-zone-head');card.style.setProperty('--zone',colors[zone]??'#99bac1');h.append(make('h2','',zone),make('span','',String(locations.filter(l=>!done(l)).length)));card.append(h);for(const l of locations){const row=make('label','available-check'),c=make('input'),text=make('span','check-name',shortLabel(l)),age=make('small','check-age',l.age);c.type='checkbox';c.checked=done(l);c.indeterminate=!c.checked&&l.members.some(singleDone);c.setAttribute('aria-label',l.name+' fait');row.title=l.members.map(m=>m.name).join('\n')+' ('+l.age+')';c.addEventListener('change',()=>{data().done??={};for(const member of l.members){data().done[member.name]=c.checked;if(['Freestanding','ActorOverride'].includes(member.type))state.notes['freestanding:'+member.name]=c.checked;}save();renderResults();});row.append(c,text);if(l.out||l.outAge){const badge=make('small','check-out',l.out?'out':'out '+l.outAge);badge.title=l.out?'Hors logique du preset : accès avec les tricks glitchless modélisés':'Accès '+l.outAge+' hors logique ; accès '+l.age+' dans la logique';row.append(badge);}row.append(age);card.append(row);}grid.append(card);}
