 function shortLabel(l){return l.label.replace(/^(?:KF|LW|SFM|HF|LLR|LH|GV|GF|GC|DMT|DMC|ZR|ZD|ZF|Kak|HC|OGC|Market|Graveyard|Deku Tree|Dodongos Cavern|Jabu Jabus Belly|Forest Temple|Fire Temple|Water Temple|Shadow Temple|Spirit Temple|Ice Cavern|Bottom of the Well|Gerudo Training Ground|Ganons Castle) /,'');}
 function request(){if(!ready)return;const snapshot={values:state.values,notes:state.notes,checks:data()};const sig=JSON.stringify({values:snapshot.values,notes:snapshot.notes,inventory:snapshot.checks.inventory,assumeKeys:snapshot.checks.assumeKeys,showOut:snapshot.checks.showOut,startAge:snapshot.checks.startAge,boulders:snapshot.checks.boulders});if(sig===lastSignature){renderResults();return;}lastSignature=sig;revision++;status.textContent='Calcul des accès…';worker.postMessage({type:'evaluate',revision,state:JSON.parse(JSON.stringify(snapshot))});}
 function start(){if(worker)return;worker=new Worker('checks-worker.js');worker.onmessage=({data:r})=>{if(r.type==='ready'){items=r.items;boulders=r.boulders;destinations=r.destinations;ready=true;inventory();destinationSuggestions();request();}else if(r.type==='result'&&r.revision===revision){lastResult=r;renderResults();}else if(r.type==='error'){status.textContent='Calcul indisponible — recharge la page pour réessayer.';status.title=r.message;grid.replaceChildren();lastSignature='';}};worker.onerror=()=>{status.textContent='La logique n’a pas pu être chargée. Recharge la page.';};worker.postMessage({type:'init',data:D});}
